## Scratch probe: clip position after play(), play()+seek(0, true), play()+seek(0, false),
## called from a host's _physics_process while another clip plays, physics callback.
class Host extends Node2D:
	var tick := -1
	var plan: Dictionary = {}
	var variant := ""
	func _physics_process(_d: float) -> void:
		tick += 1
		if plan.has(tick):
			var ap: AnimationPlayer = $AP
			ap.play(plan[tick])
			if plan[tick] == "slash" and variant == "seek_true":
				ap.seek(0.0, true)
			elif plan[tick] == "slash" and variant == "seek_false":
				ap.seek(0.0, false)
class TickLog extends Node:
	var host: Host
	var lines: PackedStringArray = []
	func _physics_process(_d: float) -> void:
		var ap: AnimationPlayer = host.get_node("AP")
		lines.append("tick %2d anim %-6s pos %.4f cell %d" % [host.tick, ap.current_animation, ap.current_animation_position if ap.current_animation != "" else -1.0, (host.get_node("Sprite") as Sprite2D).frame])
func _lib() -> AnimationLibrary:
	var lib := AnimationLibrary.new()
	var slash := Animation.new(); slash.length = 17.0 / 60.0; slash.loop_mode = Animation.LOOP_NONE
	var f := slash.add_track(Animation.TYPE_VALUE); slash.track_set_path(f, "Sprite:frame"); slash.value_track_set_update_mode(f, Animation.UPDATE_DISCRETE)
	slash.track_insert_key(f, 0.0, 10)
	lib.add_animation("slash", slash)
	var idle := Animation.new(); idle.length = 1.0; idle.loop_mode = Animation.LOOP_LINEAR
	var h := idle.add_track(Animation.TYPE_VALUE); idle.track_set_path(h, "Sprite:frame"); idle.value_track_set_update_mode(h, Animation.UPDATE_DISCRETE); idle.track_insert_key(h, 0.0, 9)
	lib.add_animation("idle", idle)
	return lib
func _init() -> void:
	_run.call_deferred()
func _run() -> void:
	for variant in ["play_only", "seek_true", "seek_false"]:
		var host := Host.new(); host.variant = variant
		var sprite := Sprite2D.new(); sprite.name = "Sprite"; sprite.hframes = 4; sprite.vframes = 4
		sprite.texture = ImageTexture.create_from_image(Image.create(1640, 1544, false, Image.FORMAT_RGBA8)); host.add_child(sprite)
		var ap := AnimationPlayer.new(); ap.name = "AP"; host.add_child(ap)
		ap.add_animation_library("", _lib())
		ap.callback_mode_process = AnimationMixer.ANIMATION_CALLBACK_MODE_PROCESS_PHYSICS
		host.plan = {0: "idle", 3: "slash", 20: "idle"}
		var logger := TickLog.new(); logger.host = host; logger.process_physics_priority = 100
		get_root().add_child(host); get_root().add_child(logger)
		for i in 24: await physics_frame
		print("VARIANT ", variant, " (slash played on tick 3 = swing tick 0; idle on tick 20 = swing tick 17)")
		for l in logger.lines: print(l)
		host.queue_free(); logger.queue_free()
		await physics_frame
	quit(0)

